mapper.select:
SELECT COALESCE(SUM(u.total_tokens), 0)
FROM dispatch_ai_usage u
WHERE u.tenant_id = #{tenantId}
  AND u.usage_at >= #{start}
  AND u.usage_at < #{end}

SELECT u.usage_at AS usageAt,
       u.total_tokens AS totalTokens
FROM dispatch_ai_usage u
WHERE u.tenant_id = #{tenantId}
  AND u.usage_at >= #{start}
  AND u.usage_at < #{end}
